<script lang="ts">
import {onMount} from 'svelte';import type {Catalog,Locale} from './locales';import Select from './components/Select.svelte';
let {t,locale,request,installAllowed}=$props<{t:Catalog;locale:Locale;request:(url:string,body?:object)=>Promise<any>;installAllowed:boolean}>();
type Info={current:string|null;latest:string|null;versions:{commit:string;source:string}[];job:{state:string;phase:string;target:string;bytes:number;error?:string}|null};
let info=$state<Info|null>(null),target=$state(''),busy=$state(false),error=$state(''),dialog=$state<HTMLDialogElement>()!;
let active=$derived(['downloading','applying'].includes(info?.job?.state??''));let options=$derived((info?.versions??[]).map(v=>({value:v.commit,label:v.commit+' · '+(v.source==='official-alpha'?t.serverOfficial:t.serverBackup)})));
async function load(){try{info=await request('/api/server-updates');error='';if(!target&&info?.latest)target=info.latest;}catch(e){error=(e as Error).message;}}
async function action(name:string){busy=true;error='';try{info=await request('/api/server-updates/'+name,{target});if(name==='check'&&!target)target=info!.latest??'';}catch(e){error=(e as Error).message;}finally{busy=false;}}
onMount(()=>{load();const timer=setInterval(load,2000);return()=>clearInterval(timer);});
</script>
<details class="bridge-settings server-updates"><summary>{t.serverUpdates}{#if active}<span role="status">{t.serverUpdating}</span>{/if}</summary><div class="update-heading"><p class="muted">{t.serverUpdateHint}</p><button disabled={busy||active} onclick={()=>action('check')}>{t.serverCheck}</button></div><div class="version-row"><span>{t.serverVersion}: <strong>{info?.current??'—'}</strong></span><span>{t.serverLatest}: <strong>{info?.latest??'—'}</strong></span></div><p class="muted">{t.serverVersionLimit}</p>{#if options.length}<Select value={target} {options} label={t.serverTarget} onchange={v=>target=v} disabled={busy||active||info?.job?.state==='ready'}/>{/if}<div class="actions"><button disabled={busy||active||!target||!installAllowed||info?.job?.state==='ready'} onclick={()=>action('download')}>{t.serverDownload}</button><button class="primary" disabled={busy||!installAllowed||info?.job?.state!=='ready'} onclick={()=>dialog.showModal()}>{t.serverInstall}</button>{#if info?.job?.state==='downloading'||info?.job?.state==='ready'}<button disabled={busy} onclick={()=>action('cancel')}>{t.cancel}</button>{/if}</div>{#if info?.job}<p role="status" class="update-status">{info.job.state==='ready'?t.serverReady:info.job.state==='completed'?t.serverCompleted:info.job.state==='failed'?t.failed:info.job.state==='cancelled'?t.updateCancelled:t.serverUpdating} · {new Intl.NumberFormat(locale).format(info.job.bytes)} B</p>{/if}{#if error||info?.job?.error}<p role="alert" class="error">{t.errors[(error||info?.job?.error) as keyof typeof t.errors]??t.errors['request.failed']}</p>{/if}</details>
<dialog bind:this={dialog} aria-labelledby="server-update-confirm"><h2 id="server-update-confirm">{t.serverConfirm}</h2><p>{t.serverConfirmBody}</p><p class="path">{info?.job?.target??target}</p><div class="actions"><button onclick={()=>dialog.close()}>{t.cancel}</button><button class="primary" onclick={()=>{dialog.close();action('apply');}}>{t.serverInstall}</button></div></dialog>
